const UUID_LIKE_THREAD_NAME_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const SHORT_HEX_THREAD_NAME_REGEX = /^[a-f0-9]{4,8}$/i;

export function looksAutoGeneratedThreadName(name: string) {
  const trimmed = name.trim();
  return (
    trimmed === "New Agent" ||
    trimmed.startsWith("Agent ") ||
    SHORT_HEX_THREAD_NAME_REGEX.test(trimmed) ||
    UUID_LIKE_THREAD_NAME_REGEX.test(trimmed)
  );
}

/** Auto-generated names keep enough of the request to read in the titlebar; lists truncate visually with CSS. */
export const THREAD_NAME_MAX = 80;
export function clampThreadName(name: string, maxLength = THREAD_NAME_MAX): string | null {
  const trimmed = name.replace(/\s+/g, " ").trim();
  if (!trimmed) {
    return null;
  }
  if (trimmed.length <= maxLength) return trimmed;
  // Cut at the last word boundary so a name never ends mid-word ("Calculat…").
  const cut = trimmed.slice(0, maxLength);
  const space = cut.lastIndexOf(" ");
  return `${(space > maxLength * 0.6 ? cut.slice(0, space) : cut).trimEnd()}…`;
}
